using System.Reflection;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;
using static TutorFlow.Core.Tests.Asistente.EscenarioAsistente;
using static TutorFlow.Core.Tests.Asistente.SeccionesDeReferencia;

namespace TutorFlow.Core.Tests.Asistente;

public sealed class ReferenciasEscritasTests
{
    private const string TipoDeLaLimpieza = "TutorFlow.Core.Asistente.ReferenciasEscritas";
    private const string MetodoDeLaLimpieza = "Limpiar";
    private const string PreguntaNotaMinima = "¿Cuál es la nota mínima para aprobar una asignatura?";
    private const string PreguntaPromedio = "¿Cuál es mi promedio ponderado del periodo?";
    private static readonly Usuario Est001 = new(Rol.Estudiante, "EST-001");
    private static readonly Usuario Est004 = new(Rol.Estudiante, "EST-004");
    private static readonly Usuario Est005 = new(Rol.Estudiante, "EST-005");
    private static readonly Cita Art3 = new(Reglamento, "Artículo 3");
    private static readonly Cita Art5 = new(Reglamento, "Artículo 5");
    private static readonly Cita Art11 = new(Reglamento, "Artículo 11");
    private static readonly Cita Art20 = new(Reglamento, "Artículo 20");
    private static readonly Cita Sec3 = new(Evaluacion, "Sección 3");
    private static readonly Cita Sec4 = new(Evaluacion, "Sección 4");
    private static readonly Cita Beca31 = new(Bienestar, "Sección 3.1");

    public static TheoryData<string[], string, string> LimpiezaUnitaria => new()
    {
        { [Texto(Art3)], "El reglamento_academico_2023.md fue derogado (reglamento_academico_2025.md · Artículo 3).", "El reglamento_academico_2023.md fue derogado (reglamento_academico_2025.md · Artículo 3)." },
        { [Texto(Art3)], "Ya no aplica reglamento_academico_2023.md · Artículo 9.", "Ya no aplica." },
        { [Texto(Sec3)], "La definitiva se calcula según evaluacion_y_calificaciones.md · Secciones 3 y 5.", "La definitiva se calcula." },
        { [Texto(Sec3), Texto(Sec4)], "Tu promedio es 4.39 (evaluacion_y_calificaciones.md · Secciones 3 y 4).", "Tu promedio es 4.39 (evaluacion_y_calificaciones.md · Secciones 3 y 4)." },
        { [Texto(Beca31)], "Requisitos: promedio 4.3 o más. Estos requisitos se respaldan en bienestar_y_becas.md · Sección 3.1.", "Requisitos: promedio 4.3 o más. Estos requisitos se respaldan en bienestar_y_becas.md · Sección 3.1." },
        { [], "El documento_academico_2025.md establece la escala.", "Establece la escala." }
    };

    private static string Limpiar(string respuesta, IReadOnlyList<Cita> citas)
    {
        var tipo = typeof(PreguntarAsistente).Assembly.GetType(TipoDeLaLimpieza)
            ?? throw new InvalidOperationException($"Core no define {TipoDeLaLimpieza} (spec 001 §11.1 'Referencias escritas en la respuesta', D-37).");
        var metodo = tipo.GetMethod(MetodoDeLaLimpieza, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static, [typeof(string), typeof(IReadOnlyList<Cita>)])
            ?? throw new InvalidOperationException($"{TipoDeLaLimpieza} no define static string {MetodoDeLaLimpieza}(string respuesta, IReadOnlyList<Cita> citas).");
        return (string)metodo.Invoke(null, [respuesta, citas])!;
    }

    private static string Texto(Cita cita) => $"{cita.Documento} · {cita.Seccion}";

    private static Cita DesdeTexto(string texto)
    {
        var partes = texto.Split(" · ");
        return new Cita(partes[0], partes[1]);
    }

    private static IndiceFijo IndiceConLasReglas(params SeccionDocumento[] entregadas) =>
        Indice(
            [NotaDefinitiva, PromedioPonderado, Articulo5, Articulo6, Articulo7, Articulo11, Articulo12, Articulo20, Articulo22, BecaPorRendimiento, Atencion],
            entregadas);

    private static string[] CitasDeDocumento(RespuestaAsistente respuesta) =>
        [.. respuesta.Citas.Where(c => c.Documento.EndsWith(".md", StringComparison.Ordinal)).Select(Texto)];

    [Theory]
    [MemberData(nameof(LimpiezaUnitaria))]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-178")]
    [Trait("COMP", "COMP-02")]
    public void ESC_178j_La_limpieza_conserva_las_referencias_validas_y_elimina_las_demas(string[] citas, string respuesta, string esperada)
    {
        var resultado = Limpiar(respuesta, [.. citas.Select(DesdeTexto)]);

        Assert.Equal(esperada, resultado);
    }

    [Fact]
    [Trait("CA", "CA-14")]
    [Trait("ESC", "ESC-178")]
    [Trait("COMP", "COMP-02")]
    public async Task ESC_178a_Una_referencia_a_un_documento_inexistente_se_elimina_y_el_respaldo_agrega_la_cita_real()
    {
        var escenario = Con(Fijo("Una asignatura se aprueba con 3.0 (documento_academico_2025.md · Artículo 5)."), IndiceConLasReglas(Articulo5));
using TutorFlow.Core.Asistente;
using TutorFlow.Pruebas.Soporte;
using static TutorFlow.Core.Tests.Asistente.EscenarioAsistente;

namespace TutorFlow.Core.Tests.Asistente;

internal static class SalidasVerificadas
{
    public static Func<SolicitudLlm, int, RespuestaLlm> LeeElProgramaYResponde(string texto) =>
        (_, llamada) => llamada == 0 ? Herramienta(HerramientasAsistente.Programa) : Texto(texto);

    public static Func<SolicitudLlm, int, RespuestaLlm> LeeElProgramaYElDetalleYResponde(string texto, string estudianteId) =>
        (_, llamada) => llamada == 0
            ? new RespuestaLlm(
                null,
                [
                    new LlamadaHerramienta("lectura-programa", HerramientasAsistente.Programa, "{}"),
                    new LlamadaHerramienta("lectura-detalle", HerramientasAsistente.Estudiante, $$"""{"{{HerramientasAsistente.ParametroEstudianteId}}":"{{estudianteId}}"}""")
                ],
                new UsoTokens(10, 5),
                false)
            : Texto(texto);

    public static void AfirmarEstadoNoVerificado(ResultadoPregunta resultado, EscenarioAsistente escenario, bool usoDatos)
    {
        var respuesta = resultado.Respuesta!;
        Assert.Equal(Textos.NoVerificable, respuesta.Respuesta);
        Assert.Empty(respuesta.Citas);
        Assert.Equal(usoDatos, respuesta.UsoDatosEstudiante);
        Assert.Equal(ResultadosNuevosDeAuditoria.EstadoNoVerificado, resultado.Auditoria);
        Assert.Equal(ResultadosNuevosDeAuditoria.EstadoNoVerificado, Assert.Single(escenario.Auditoria.Eventos).Resultado);
    }

    public static void AfirmarRespondida(ResultadoPregunta resultado, EscenarioAsistente escenario, string texto)
    {
        Assert.Equal(ResultadoAuditoria.Respondida, resultado.Auditoria);
        Assert.Equal(texto, resultado.Respuesta!.Respuesta);
        Assert.True(resultado.Respuesta.UsoDatosEstudiante);
        Assert.Equal(ResultadoAuditoria.Respondida, Assert.Single(escenario.Auditoria.Eventos).Resultado);
    }
}
using TutorFlow.Core.Asistente;

namespace TutorFlow.Pruebas.Soporte;

public static class CatalogoDePrueba
{
    public static IReadOnlyList<AsignaturaCatalogo> Asignaturas { get; } =
    [
        new("CAL-201", "Cálculo Integral"),
        new("POO-202", "Programación Orientada a Objetos"),
        new("BD-203", "Bases de Datos"),
        new("ING-204", "Inglés III"),
        new("CON-101", "Contabilidad"),
        new("MIC-102", "Microeconomía"),
        new("EST-103", "Estadística"),
        new("COM-104", "Comunicación Oral y Escrita")
    ];
}
using System.Text.RegularExpressions;
using TutorFlow.Core.Academico;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Core.Tests.Asistente;

internal sealed class ApiAcademicaDoble(DatosAcademicos datos) : IApiAcademica
{
    public List<string> LecturasNotas { get; } = [];

    public List<string> LecturasAsistencia { get; } = [];

    public Task<Estudiante?> ObtenerEstudianteAsync(string id, CancellationToken cancellationToken) =>
        Task.FromResult(datos.Estudiantes.FirstOrDefault(e => e.Id == id));

    public Task<Coordinador?> ObtenerCoordinadorAsync(string id, CancellationToken cancellationToken) =>
        Task.FromResult(datos.Coordinadores.FirstOrDefault(c => c.Id == id));

    public Task<IReadOnlyList<NotasAsignatura>> ObtenerNotasAsync(string estudianteId, CancellationToken cancellationToken)
    {
        LecturasNotas.Add(estudianteId);
        return Task.FromResult(datos.NotasDe(estudianteId));
    }

    public Task<IReadOnlyList<AsistenciaAsignatura>> ObtenerAsistenciaAsync(string estudianteId, CancellationToken cancellationToken)
    {
        LecturasAsistencia.Add(estudianteId);
        return Task.FromResult(datos.AsistenciaDe(estudianteId));
    }

    public Task<IReadOnlyList<Estudiante>> ObtenerEstudiantesDeProgramaAsync(string programaId, CancellationToken cancellationToken) =>
        Task.FromResult<IReadOnlyList<Estudiante>>([.. datos.Estudiantes.Where(e => e.ProgramaId == programaId)]);

    public Task<IReadOnlyList<Programa>> ObtenerProgramasAsync(CancellationToken cancellationToken) =>
        Task.FromResult(datos.Programas);
}

internal sealed class LlmDoble(Func<SolicitudLlm, int, RespuestaLlm> guion) : IClienteLlm
{
    public List<SolicitudLlm> Solicitudes { get; } = [];

    public Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
    {
        Solicitudes.Add(solicitud);
        return Task.FromResult(guion(solicitud, Solicitudes.Count - 1));
    }

    public string TextoDeLlamada(int indice) =>
        string.Join("\n", Solicitudes[indice].Mensajes.Select(m => m.Contenido));
}

internal sealed class IndiceFijo(IReadOnlyList<SeccionDocumento> indice, IReadOnlyList<SeccionDocumento> entregadas) : IBaseConocimiento
{
    public IReadOnlyList<SeccionDocumento> BuscarSecciones(string consulta, int maximo) => entregadas;


    public SeccionDocumento? ObtenerSeccion(Cita cita) =>
        indice.FirstOrDefault(s => s.Documento == cita.Documento && s.Seccion == cita.Seccion);
}

internal sealed class IndiceRelevante : IBaseConocimiento
{
    public IReadOnlyList<SeccionDocumento> BuscarSecciones(string consulta, int maximo) =>
        [new SeccionDocumento("reglamento_academico_2025.md", "Artículo 99", "Ley", consulta)];


    public SeccionDocumento? ObtenerSeccion(Cita cita) => null;
}

internal sealed class AuditoriaDoble : IAuditoria
{
    public List<EventoAuditoria> Eventos { get; } = [];

    public void Registrar(EventoAuditoria evento) => Eventos.Add(evento);

    public void RegistrarMultiplesIdentidades(EventoMultiplesIdentidades evento)
    {
    }
}

internal sealed class RelojFijo : IReloj
{
    public DateTimeOffset AhoraUtc { get; } = new(2026, 11, 22, 12, 0, 0, TimeSpan.Zero);
}

internal sealed class EscenarioAsistente
{
    public const string PreguntaPromedio = "¿Cuál es mi promedio?";

    private readonly PreguntarAsistente _asistente;

    private EscenarioAsistente(Func<SolicitudLlm, int, RespuestaLlm> guion, IBaseConocimiento baseConocimiento, string? canario, DatosAcademicos datos)
    {
        var reloj = new RelojFijo();
        var limites = new LimitesAsistente();
        Api = new ApiAcademicaDoble(datos);
        Llm = new LlmDoble(guion);
        Auditoria = new AuditoriaDoble();
        _asistente = new PreguntarAsistente(
            Api,
            Llm,
            baseConocimiento,
            new AuditorPeticiones(Auditoria, reloj),
            new PoliticaAcceso(),
            new VerificadorSalida(),
            limites,
            new ConfiguracionAsistente(null, canario, datos.Directorio.CodigosAsignatura, catalogo: CatalogoDePrueba.Asignaturas),
            new PresupuestoDiario(reloj, limites));
    }

    public ApiAcademicaDoble Api { get; }

    public LlmDoble Llm { get; }

    public AuditoriaDoble Auditoria { get; }

    public static EscenarioAsistente Con(
        Func<SolicitudLlm, int, RespuestaLlm> guion,
        IBaseConocimiento? baseConocimiento = null,
        string? canario = null,
        DatosAcademicos? datos = null) =>
        new(guion, baseConocimiento ?? new IndiceRelevante(), canario, datos ?? DatosReferencia.Cargar());

    public static RespuestaLlm Texto(string texto) => new(texto, [], new UsoTokens(10, 5), false);

    public static RespuestaLlm Herramienta(string nombre, string argumentosJson = "{}") =>
        new(null, [new LlamadaHerramienta("llamada-1", nombre, argumentosJson)], new UsoTokens(10, 5), false);

    public static Func<SolicitudLlm, int, RespuestaLlm> Fijo(string texto) => (_, _) => Texto(texto);

    public static string FragmentoDelPrompt(string prompt, int palabras)
    {
        var tokens = prompt.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries);
        var fijos = TextosFijosNormalizados();
        for (var inicio = 0; inicio + palabras <= tokens.Length; inicio++)
        {
            var ventana = tokens[inicio..(inicio + palabras)];
