                ? new RespuestaLlm(null, [Llamada("pide-1", herramienta.Nombre, JsonSerializer.Serialize(new Dictionary<string, string> { [ParametroEstudianteId] = estudianteId }))], uso ?? UsoPorDefecto, false)
