using System.Text.Json;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;
using TutorFlow.Infrastructure.Auditoria;
using TutorFlow.Pruebas.Soporte;

namespace TutorFlow.Api.Tests.Infraestructura;

[Collection("Consola")]
public sealed class AuditoriaConsolaTests
{
    private static readonly DateTimeOffset Instante = new(2026, 11, 22, 12, 0, 0, TimeSpan.Zero);

    public static TheoryData<ResultadoAuditoria, string> Resultados => new()
    {
        { ResultadoAuditoria.Respondida, "respondida" },
        { ResultadoAuditoria.SinInformacion, "sin_informacion" },
        { ResultadoAuditoria.Denegada, "denegada" },
        { ResultadoAuditoria.Invalida, "invalida" },
        { ResultadoAuditoria.FugaBloqueada, "fuga_bloqueada" },
        { ResultadoAuditoria.NumeroNoVerificado, "numero_no_verificado" },
        { ResultadoAuditoria.LimiteHerramientas, "limite_herramientas" },
        { ResultadoAuditoria.Error, "error" }
    };

    public static TheoryData<MotivoDenegacion, string> Motivos => new()
    {
        { MotivoDenegacion.IdentidadInvalida, "identidad_invalida" },
        { MotivoDenegacion.TerceroMencionado, "tercero_mencionado" },
        { MotivoDenegacion.ProgramaAjeno, "programa_ajeno" },
        { MotivoDenegacion.Agregado, "agregado" },
        { MotivoDenegacion.HerramientaIdAjeno, "herramienta_id_ajeno" }
    };

    private static EventoAuditoria Evento(string correlacion, string pregunta = "¿Cuál es mi promedio?", ResultadoAuditoria resultado = ResultadoAuditoria.Respondida, MotivoDenegacion? motivo = null) =>
        new(
            Instante,
            correlacion,
            "10.0.0.5",
            Rol.Estudiante,
            "EST-001",
            pregunta,
            resultado,
            motivo,
            ["EST-001"],
            [RecursoConsultado.DatosBasicos, RecursoConsultado.Notas, RecursoConsultado.Asistencia, RecursoConsultado.Programa],
            [new Cita("Datos del estudiante", "Notas")],
            1200,
            0.002m,
            35,
            false);

    private static string Capturar(Action accion)
    {
        var original = Console.Out;
        using var escritor = new StringWriter();
        Console.SetOut(escritor);
        try
        {
            accion();
        }
        finally
        {
            Console.SetOut(original);
        }

        return escritor.ToString();
    }

using System.Diagnostics;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Operacion;

public sealed class ResilienciaApiTests
{
    private const string Pregunta = "¿Cuál es mi promedio?";

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-108")]
    public async Task ESC_108_Api_academica_caida_responde_503_generico_sin_detalles_internos()
    {
        using var fabrica = new FabricaApi(api: ApiAcademicaDoble.Caida());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Pregunta);

        Afirmaciones.ProblemDetails(respuesta, 503);
        Assert.DoesNotContain("api academica caida", respuesta.Texto, StringComparison.OrdinalIgnoreCase);
        Assert.Equal(0, fabrica.Llm.Llamadas);
        Assert.Equal(ResultadoAuditoria.Error, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-108")]
    [Trait("SEG", "SEG-13")]
    public async Task ESC_108_Api_academica_que_no_responde_produce_503_en_menos_de_7_segundos()
    {
        using var fabrica = new FabricaApi(api: ApiAcademicaDoble.QueNuncaResponde());
        var reloj = Stopwatch.StartNew();

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Pregunta);

        reloj.Stop();
        Afirmaciones.ProblemDetails(respuesta, 503);
        Assert.True(reloj.Elapsed < TimeSpan.FromSeconds(7), $"tardó {reloj.Elapsed}");
    }

    [Theory]
    [InlineData("http")]
    [InlineData("cancelado")]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-109")]
    public async Task ESC_109_Llm_caido_o_con_timeout_responde_503_sin_url_modelo_ni_llave(string falla)
    {
        Exception excepcion = falla == "http"
            ? new HttpRequestException("fallo en https://api.anthropic.com con sk-ant-SECRETO modelo claude-haiku-5-5")
            : new TaskCanceledException("timeout https://api.anthropic.com sk-ant-SECRETO");
        var entorno = new Dictionary<string, string?> { ["LLM_API_KEY"] = "sk-ant-SECRETO" };
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.Falla(excepcion), variablesEntorno: entorno);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es la nota mínima para aprobar?");

        Afirmaciones.ProblemDetails(respuesta, 503);
        Assert.DoesNotContain("anthropic", respuesta.Texto, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("SECRETO", respuesta.Texto, StringComparison.Ordinal);
        Assert.DoesNotContain("haiku", respuesta.Texto, StringComparison.OrdinalIgnoreCase);

