import fs from 'node:fs';
const x = fs.readFileSync(process.argv[2], 'utf8');
const bloques = x.split('<UnitTestResult ').slice(1);
const porMetodo = new Map();
let total = 0, failed = 0;
for (const b of bloques) {
  total++;
  const name = (/testName="([^"]*)"/.exec(b) || [, ''])[1].replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#xD;|&#xA;/g, ' ');
  const outcome = (/outcome="([^"]*)"/.exec(b) || [, ''])[1];
  const metodo = name.replace(/^TutorFlow\.(Core|Api)\.Tests\./, '').replace(/\(.*$/s, '');
  const e = porMetodo.get(metodo) || { total: 0, rojos: 0, msg: '' };
  e.total++;
  if (outcome === 'Failed') {
    failed++;
    e.rojos++;
    if (!e.msg) e.msg = (/<Message>([\s\S]*?)<\/Message>/.exec(b) || [, ''])[1].replace(/&#xD;|&#xA;|\s+/g, ' ').replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').slice(0, 130);
  }
  porMetodo.set(metodo, e);
}
console.log(`total=${total} failed=${failed}`);
const filtro = process.argv[3];
for (const [m, e] of porMetodo) {
  if (filtro && !m.includes(filtro)) continue;
  if (e.rojos > 0 || process.argv[4] === 'todos') console.log(`${e.rojos}/${e.total} ${m} => ${e.msg}`);
}

