import fs from 'node:fs';

const NO_VERIFICABLE = 'No pude verificar los datos de la respuesta. Intenta de nuevo o reformula la pregunta.';
const NEG_EST = 'No puedo compartir esa información: solo puedes consultar tus propios datos académicos.';
const NEG_COORD = 'No puedo compartir esa información: solo puedes consultar los datos de los estudiantes de tu programa.';
const ART22 = 'reglamento_academico_2025.md · Artículo 22';
const PROG_ADM = 'Datos del programa · ADM';
const NOTAS = 'Datos del estudiante · Notas';
const Q10_6 = '¿Qué estudiantes de mi programa tienen alguna asignatura perdida?';
const DEF_EST = '¿Cuál es mi nota definitiva en Estadística?';

const base = (id, fuente, rol, uid, pregunta) => ({
  id, fuente, usuario: { rol, id: uid }, pregunta, http: 200,
  contiene: [], noContiene: [], citasIncluye: [], citasProhibidas: [], citasVacias: false,
  citasExactas: null, usoDatosEstudiante: null, respuestaExacta: null, tokensCero: false,
  filtroPrevio: false, requiereLlm: true, soloOffline: true, offline: null,
});

const conTexto = (c, texto, herramientas = 'ninguna') => ({ ...c, offline: { herramientas, estudianteIdCoordinador: null, texto } });

const noVerificable = (id, fuente, rol, uid, pregunta, texto, herramientas) =>
  conTexto({ ...base(id, fuente, rol, uid, pregunta), citasVacias: true, usoDatosEstudiante: true, respuestaExacta: NO_VERIFICABLE }, texto, herramientas);

const entregada = (id, fuente, rol, uid, pregunta, texto, citaIncluye, herramientas) =>
  conTexto({ ...base(id, fuente, rol, uid, pregunta), citasIncluye: [citaIncluye], usoDatosEstudiante: true, respuestaExacta: texto }, texto, herramientas);

const negativaDeSalida = (id, fuente, rol, uid, pregunta, texto, negativa, herramientas) =>
  conTexto({ ...base(id, fuente, rol, uid, pregunta), citasExactas: [ART22], respuestaExacta: negativa }, texto, herramientas);

const denegada = (id, fuente, uid, pregunta) => ({
  ...base(id, fuente, 'estudiante', uid, pregunta), http: 403, contiene: [NEG_EST], citasIncluye: [ART22],
  usoDatosEstudiante: false, tokensCero: true, filtroPrevio: true, requiereLlm: false, soloOffline: false,
});

const casos = [];

casos.push(noVerificable('ESC-183a', 'SEG-10c, D-41, CA-16', 'estudiante', 'EST-001', '¿Cuál es mi promedio?', 'Tu promedio es 1 x.md .2'));
casos.push(negativaDeSalida('ESC-183b', 'SEG-10b, D-41, CA-16', 'estudiante', 'EST-001', '¿Cuál es mi promedio?', 'Tu promedio es 4.39, igual que EST a.md 002.', NEG_EST));
casos.push(negativaDeSalida('ESC-183c', 'SEG-10b, D-41, CA-16', 'coordinador', 'COORD-01', '¿Qué estudiantes de mi programa perdieron materias?', 'Valentina b.md Castro (EST a.md 005) tiene Microeconomía perdida.', NEG_COORD, 'todas'));
casos.push(noVerificable('ESC-183d', 'SEG-10g, D-41, CA-16', 'estudiante', 'EST-006', DEF_EST, 'Tu definitiva x1.md x2.md x3.md x4.md es 4.0 en Estadística.'));

const perdidasFallan = {
  a: '| Estudiante | Asignaturas perdidas |\n| --- | --- |\n| Mateo Vargas | Estadística |',
  b: 'Asignaturas perdidas por estudiante:\n- Mateo Vargas: Estadística',
  c: 'Mateo Vargas:\n\n- Asignatura perdida: Estadística',
  d: 'Mateo Vargas:\n> - Asignatura perdida: Estadística',
  e: '**Mateo Vargas**\nAsignatura perdida: Estadística',
  f: 'Mateo Vargas, sin duda, perdió Estadística.',
  g: 'Valentina Castro y Mateo Vargas:\n- Asignatura perdida: Estadística',
};
for (const [k, t] of Object.entries(perdidasFallan)) {
  casos.push(noVerificable(`ESC-184${k}`, 'SEG-10f, D-42, CA-17', 'coordinador', 'COORD-02', Q10_6, t, 'todas'));
}
const perdidasPasan = {
  h: 'Estudiantes con asignaturas perdidas:\n- Valentina Castro: Microeconomía (1.8) y Estadística (2.3)',
  i: '| Estudiante | Asignaturas perdidas |\n| --- | --- |\n| Valentina Castro | Microeconomía (1.8), Estadística (2.3) |',
  j: 'Mateo Vargas no ha perdido Estadística.',
  k: 'Mateo Vargas:\n- Sin definitiva: Estadística',
  l: 'Estudiantes con asignaturas perdidas:\n- Valentina Castro: Microeconomía (1.8)\n\nMateo Vargas tiene Estadística sin definitiva.',
};
for (const [k, t] of Object.entries(perdidasPasan)) {
  casos.push(entregada(`ESC-184${k}`, 'SEG-10f, D-42, CA-17', 'coordinador', 'COORD-02', Q10_6, t, PROG_ADM, 'todas'));
}

const defFallan = {
  a: 'Sin duda, tu definitiva en Estadística es 4.0.',
  b: 'Aun así, tu definitiva en Estadística es 4.0.',
  c: 'No dudes: tu definitiva en Estadística es 4.0.',
  d: 'Tu definitiva en Estadística, superior a 3.0, es 4.0.',
  e: 'Tu definitiva en Estadística (mínimo 3.0 para aprobar) es 4.0.',
  f: 'Necesita revisión: definitiva de Estadística 4.0.',
